use crate::*;
use super::{policy,snapshot,state};
use std::collections::BTreeMap;
use sha2::{Digest,Sha256};
const ROOTS:&[&str]=&["mods","config","defaultconfigs","kubejs","scripts","resourcepacks","shaderpacks","options.txt"];
fn preserve_disabled(root:&Path,staged:&Path,baseline:&BTreeMap<String,String>)->Result<()>{
 let old=read_json(&policy::under(root,"installed-projects.json")?).unwrap_or_else(|_|json!({}));let mut next=read_json(&policy::under(staged,"installed-projects.json")?).unwrap_or_else(|_|json!({}));
 for path in baseline.keys().filter(|p|p.starts_with("mods/")&&p.ends_with(".jar")){
  if !policy::under(root,&format!("{path}.disabled"))?.is_file(){continue;}
  let matching=old.as_object().into_iter().flatten().find(|(_,v)|v["file"].as_str()==path.strip_prefix("mods/"));
  let target=matching.and_then(|(id,_)|next[id]["file"].as_str()).map(|s|format!("mods/{s}")).or_else(||policy::under(staged,path).ok().filter(|p|p.exists()).map(|_|path.clone())).ok_or("源包包含手动禁用的模组，但新版缺少可核验的对应记录；为避免重新启用，请先在模组管理核对该模组后更新。")?;
  let from=policy::under(staged,&target)?;if from.is_file(){let to=policy::under(staged,&format!("{target}.disabled"))?;std::fs::rename(from,to).map_err(err)?;if let Some((id,_))=matching{next[id]["file"]=json!(format!("{}.disabled",target.strip_prefix("mods/").unwrap()));}}
 }
 write_json(&policy::under(staged,"installed-projects.json")?,&next)
}
fn merge_lock(root:&Path,staged:&Path)->Result<()>{let mut merged=read_json(&policy::under(root,"installed-projects.json")?).unwrap_or_else(|_|json!({}));let incoming=read_json(&policy::under(staged,"installed-projects.json")?).unwrap_or_else(|_|json!({}));if !merged.is_object(){merged=json!({});}for(key,value)in incoming.as_object().into_iter().flatten(){if let Some(file)=value["file"].as_str(){safe_name(file)?;if policy::under(root,&format!("mods/{file}"))?.is_file(){merged[key]=value.clone();}}}merged.as_object_mut().unwrap().retain(|_,value|value["file"].as_str().is_some_and(|file|safe_name(file).is_ok()&&policy::under(root,&format!("mods/{file}")).is_ok_and(|p|p.is_file())));write_json(&policy::under(root,"installed-projects.json")?,&merged)}
pub fn managed_path(path:&str)->bool{ROOTS.iter().any(|r|path==*r||path.starts_with(&format!("{r}/")))&&!path.ends_with(".kxl-agent-backup")&&!path.to_lowercase().ends_with(".exe")&&!path.to_lowercase().ends_with(".bat")&&!path.to_lowercase().ends_with(".ps1")&&!path.split('/').any(|s|s=="logs"||s=="saves"||s=="crash-reports")}
pub fn inventory(root:&Path)->Result<BTreeMap<String,String>>{fn walk(root:&Path,path:&str,out:&mut BTreeMap<String,String>)->Result<()>{let file=policy::under(root,path)?;if !file.exists(){return Ok(());}if file.is_dir(){for e in std::fs::read_dir(file).map_err(err)?{let e=e.map_err(err)?;let name=e.file_name().into_string().map_err(|_|"资源文件名无效")?;walk(root,&format!("{path}/{name}"),out)?;}}else if managed_path(path){if out.len()>=20000{return Err("整合包管理文件超过 20000 个，请使用手动导入。".into());}out.insert(path.into(),snapshot::hash(&file)?);}Ok(())}let mut files=BTreeMap::new();for path in ROOTS{walk(root,path,&mut files)?;}Ok(files)}
pub fn record_source(core:&Core,instance:&mut Value,source:Value)->Result<()> {let id=string(instance,"id")?;let root=core.instance(id)?;instance["packSource"]=source;match inventory(&root){Ok(files)=>instance["packManagedFiles"]=json!(files),Err(_)=>{instance["packManagedFiles"]=Value::Null;instance["packSourceWarning"]=json!("未能建立管理文件清单，在线更新前需重新导入；不会覆盖未知用户文件。");}}write_json(&root.join("kxl.json"),instance)}
pub fn digest(value:&Value)->String{format!("{:x}",Sha256::digest(value.to_string()))}
pub fn identities(core:&Core,id:&str)->Result<Vec<Value>>{let root=core.instance(id)?;let lock=read_json(&policy::under(&root,"installed-projects.json")?).unwrap_or_else(|_|json!({}));let mut result=Vec::new();for(key,v)in lock.as_object().into_iter().flatten(){let Some(file)=v["file"].as_str()else{continue};safe_name(file)?;if !policy::under(&root,&format!("mods/{file}"))?.is_file(){continue;}let source=if key.starts_with("cf-"){"curseforge"}else{"modrinth"};let pid=key.strip_prefix("cf-").unwrap_or(key);let vid=v["version"].as_str().map(str::to_owned).or_else(||v["version"].as_u64().map(|n|n.to_string())).unwrap_or_default();if !vid.is_empty(){result.push(json!({"source":source,"projectId":pid,"versionId":vid,"name":file,"file":file}));}}Ok(result)}
async fn latest(core:&Core,cfg:&Value)->Result<Value>{let src=&cfg["packSource"];let pid=string(src,"projectId")?;safe_name(pid)?;let game=string(cfg,"version")?;let loader=string(cfg,"loader")?;if src["provider"]=="modrinth"{let mut url=reqwest::Url::parse(&format!("https://api.modrinth.com/v2/project/{pid}/version")).map_err(err)?;url.query_pairs_mut().append_pair("game_versions",&json!([game]).to_string()).append_pair("loaders",&json!([loader]).to_string());let rows=core.get(url.as_str()).await?;let v=rows.as_array().into_iter().flatten().find(|v|v["version_type"]=="release").ok_or("没有兼容的正式整合包版本")?;let file=v["files"].as_array().into_iter().flatten().find(|v|v["filename"].as_str().is_some_and(|s|s.ends_with(".mrpack"))).ok_or("新版本未提供 mrpack")?;Ok(json!({"provider":"modrinth","projectId":pid,"versionId":v["id"],"name":src["name"],"versionNumber":v["version_number"],"notes":ai_diagnose::agent_text(v["changelog"].as_str().unwrap_or("")).chars().take(10000).collect::<String>(),"estimatedDownloadBytes":file["size"],"archive":{"url":file["url"],"sha1":file["hashes"]["sha1"],"size":file["size"]}}))}else if src["provider"]=="curseforge"{let key=curseforge::configured_key(core,"");let v=curseforge::best_file(core,pid.parse().map_err(|_|"整合包项目 ID 无效")?,Some(game),Some(loader),key.as_deref()).await?;Ok(json!({"provider":"curseforge","projectId":pid,"versionId":v["id"].as_u64().map(|n|n.to_string()),"name":src["name"],"versionNumber":v["displayName"],"notes":"请在项目发布页核对版本说明；暂未取得变更文本。","estimatedDownloadBytes":v["fileLength"],"archive":{"url":curseforge::download_url(&v)?,"sha1":curseforge::file_hash(&v),"size":v["fileLength"]}}))}else{Err("此实例未记录可查询的整合包来源，请先从 Modrinth 或 CurseForge 安装整合包。".into())}}
pub async fn check(core:&Core,id:&str)->Result<Value>{let cfg=read_json(&core.instance(id)?.join("kxl.json"))?;if !cfg["packSource"].is_object(){return Ok(json!({"available":false,"reason":"此实例没有在线整合包来源；手动搭建的包可使用模组更新或版本迁移。"}));}let candidate=latest(core,&cfg).await?;let current=inventory(&core.instance(id)?)?;let baseline: BTreeMap<String,String>=serde_json::from_value(cfg["packManagedFiles"].clone()).unwrap_or_default();let modified=current.iter().filter(|(p,h)|baseline.get(*p)!=Some(*h)).map(|(p,_)|p.clone()).collect::<Vec<_>>();let available=candidate["versionId"]!=cfg["packSource"]["versionId"];let incoming=if available{super::update_manifest::manifest(core,&candidate).await?}else{json!({"files":{},"downloadBytes":0})};if available&&incoming["minecraft"]!=cfg["version"]{return Err("新归档的游戏版本不同，请使用迁移功能。".into());}let differences=if available{super::update_manifest::differences(&core.instance(id)?,&baseline,&incoming["files"])?}else{json!({})};let preview=json!({"available":available,"differences":differences,"downloadBytes":incoming["downloadBytes"],"current":cfg["packSource"],"candidate":candidate,"preservedUserFiles":modified,"warnings":["已核验新归档并列出文件差异；用户配置、存档和自行添加/修改的文件默认保留。","展示的下载体积仅为发行归档，实际游戏、模组和前置仍受 2 GB 任务预算限制。"]});Ok(json!({"updateHash":digest(&preview),"preview":preview}))}
pub fn merge(root:&Path,staged:&Path,baseline:&BTreeMap<String,String>,next:&BTreeMap<String,String>)->Result<(BTreeMap<String,String>,Vec<String>)>{let mut managed=BTreeMap::new();let mut preserved=Vec::new();for(path,hash)in next{if !managed_path(path){return Err("更新清单包含非白名单路径".into());}let target=policy::under(root,path)?;let source=policy::under(staged,path)?;if snapshot::hash(&source)?!=*hash{return Err("暂存更新文件校验失败".into());}let user_config=path=="options.txt"||path.starts_with("config/")||path.starts_with("defaultconfigs/");if target.exists()&&(user_config||baseline.get(path).is_none_or(|h|snapshot::hash(&target).ok().as_ref()!=Some(h))){preserved.push(path.clone());continue;}std::fs::create_dir_all(target.parent().unwrap()).map_err(err)?;snapshot::replace_file(&source,&target).map_err(|e|format!("无法替换 {path}：{e}"))?;managed.insert(path.clone(),hash.clone());}for(path,hash)in baseline{if !managed_path(path){return Err("旧管理清单包含不允许的路径".into());}if next.contains_key(path)||path=="options.txt"||path.starts_with("config/")||path.starts_with("defaultconfigs/"){continue;}let target=policy::under(root,path)?;if target.exists()&&snapshot::hash(&target)?==*hash{std::fs::remove_file(target).map_err(err)?;}else if target.exists(){preserved.push(path.clone());}}Ok((managed,preserved))}
pub async fn apply(core:&Core,task:&mut state::Task,args:&Value,account:&str,settings:&Value)->Result<Value>{if account.is_empty(){return Err("更新需要启动验证，请先选择游戏账号。".into());}super::verify::ensure_idle()?;let expected=string(args,"updateHash")?;let preview=check(core,&task.instance_id).await?;if preview["updateHash"]!=expected{return Err("更新计划已改变，请重新检查并确认。".into());}if preview["preview"]["available"]!=true{return Err("当前没有待更新版本。".into());}let candidate=&preview["preview"]["candidate"];let root=core.instance(&task.instance_id)?;let original=read_json(&root.join("kxl.json"))?;let baseline: BTreeMap<String,String>=serde_json::from_value(original["packManagedFiles"].clone()).map_err(|_|"此包缺少初始文件清单，请重新导入后再使用在线更新。")?;let sid=snapshot::create(core,&task.instance_id)?;task.snapshots.push(sid.clone());state::save(core,task,"state")?;
 let payload=json!({"source":candidate["provider"],"project":if candidate["provider"]=="curseforge"{json!(string(candidate,"projectId")?.parse::<u64>().map_err(|_|"项目 ID 无效")?)}else{candidate["projectId"].clone()},"versionId":candidate["versionId"],"name":format!("更新暂存 {}",task.id),"settings":original["settings"],"game":original["version"],"loader":original["loader"]});
 let staged=if candidate["provider"]=="curseforge"{curseforge::install_modpack(core,&payload).await?}else{packs::install_modrinth(core,&payload).await?};let staged_id=string(&staged,"id")?.to_owned();let staged_root=core.instance(&staged_id)?;if staged_id==task.instance_id{return Err("更新暂存实例与源实例相同，已拒绝。".into());}
 let result=async{super::verify::ensure_idle()?;if staged["version"]!=original["version"]||staged["loader"]!=original["loader"]{return Err("此更新需要更改游戏或加载器，请改用版本迁移。".into());}preserve_disabled(&root,&staged_root,&baseline)?;let next=inventory(&staged_root)?;let (managed,preserved)=merge(&root,&staged_root,&baseline,&next)?;for file in ["version.json","client.jar"]{let source=policy::under(&staged_root,file)?;if source.exists(){snapshot::replace_file(&source,&policy::under(&root,file)?).map_err(|e|format!("无法替换 {file}：{e}"))?;}}
 merge_lock(&root,&staged_root)?;let mut cfg=original.clone();cfg["loaderVersion"]=staged["loaderVersion"].clone();cfg["packSource"]=staged["packSource"].clone();cfg["packSource"]["name"]=original["packSource"]["name"].clone();cfg["packManagedFiles"]=json!(managed);write_json(&root.join("kxl.json"),&cfg)?;let rows=resources::list(core,&json!({"id":task.instance_id,"kind":"mods"}))?;let warnings=rows.as_array().into_iter().flatten().flat_map(|r|r["problems"].as_array().into_iter().flatten()).filter_map(Value::as_str).collect::<std::collections::BTreeSet<_>>().into_iter().take(24).map(|warning|format!("静态检查：{warning}。内嵌依赖由加载器解析，以实际启动为准。" )).collect::<Vec<_>>();if account.is_empty(){return Err("更新需要启动验证，请选择游戏账号后重试。".into());}let verified=super::verify::run(core,&task.instance_id,account,settings).await?;Ok(json!({"updated":true,"packSource":cfg["packSource"],"preservedUserFiles":preserved,"warnings":warnings,"rollbackSnapshotId":sid,"report":verified}))}.await;
 if result.is_err(){snapshot::restore(core,&task.instance_id,&sid)?;}if policy::absolute(&core.root,&staged_root).is_ok()&&staged_root.canonicalize().is_ok_and(|p|p.starts_with(core.root.join("instances").canonicalize().unwrap_or_default())){let _=std::fs::remove_dir_all(staged_root);}result
}
#[cfg(test)]mod tests{use super::*;#[test]fn merge_preserves_worlds_user_mods_and_configs(){let a=tempfile::tempdir().unwrap();let b=tempfile::tempdir().unwrap();for(dir,file,text)in[(a.path(),"mods/old.jar","old"),(a.path(),"mods/user.jar","user"),(a.path(),"config/a.json","custom"),(a.path(),"saves/World/level.dat","world"),(b.path(),"mods/new.jar","new"),(b.path(),"config/a.json","default")]{let path=dir.join(file);std::fs::create_dir_all(path.parent().unwrap()).unwrap();std::fs::write(path,text).unwrap();}let old=inventory(a.path()).unwrap();let next=inventory(b.path()).unwrap();let mut baseline=old;baseline.remove("mods/user.jar");let(_,preserved)=merge(a.path(),b.path(),&baseline,&next).unwrap();assert!(preserved.contains(&"config/a.json".into()));assert_eq!(std::fs::read_to_string(a.path().join("config/a.json")).unwrap(),"custom");assert!(!a.path().join("mods/old.jar").exists());assert!(a.path().join("mods/user.jar").exists());assert!(a.path().join("saves/World/level.dat").exists());}#[test]fn managed_paths_reject_executables(){for p in ["saves/world","logs/latest.log","config/run.ps1","mods/run.exe"]{assert!(!managed_path(p));}assert!(managed_path("kubejs/server_scripts/recipes.js"));}}
